j:jelly.g:evaluate:
var value = jelly.jvar_value;

if (typeof jelly.jvar_value != "string") {
	value = JSON.stringify(jelly.jvar_value, null, 4);
}

value;

j:jelly.script:
(function() {
	var cmEditor = CodeMirror.fromTextArea(document.getElementById("${ref}"), {
		value: "${JS:jvar_string_value}",
		mode: "application/ld+json",
		lineNumbers: true,
		gutters: ["CodeMirror-linenumbers", "CodeMirror-foldgutter", "CodeMirror-lint-markers", "cm-color-preview"],
		foldGutter: true,
		tabMode: "indent",
		indentUnit: 4,
		indentWithTabs: false,
		lint: true,
		readOnly: false
	});

	// parse out any colors on init
	cmEditor.operation(function() {
		var doc = cmEditor.getDoc();
		doc.eachLine(function(line) {
			renderColorPreviewMarker(doc, line);
		});
	});

	function renderColorPreviewMarker(doc, line) {
		var bgMarker = getColorMarkerForString(line.text);
		doc.setGutterMarker(line, "cm-color-preview", bgMarker);
	}

	function getColorMarkerForString(text) {
		var rgbRegex = /(\d+\s*,\s*\d+\s*,\s*\d+)/ig;
		var rgb = text.match(rgbRegex)
		if (!rgb)
			return;
		var marker = document.createElement("div");
		marker.addClassName("cm-color-preview-marker");
		marker.style.backgroundColor = "rgb(" + rgb + ")";
		return marker;
	}

	var renderLineTimeout;
	var updatedLines = [];
	function processUpdatedLines(doc) {
		doc.operation(function() {
			for(var i=0; i ${LT} updatedLines.length; i++) {
				renderColorPreviewMarker(doc, updatedLines[i]);
			}
			updatedLines = [];
		});
	}
	cmEditor.on("renderLine", function(doc, line, el) {
		updatedLines.push(line);
		clearTimeout(renderLineTimeout);
		renderLineTimeout = setTimeout(function(){ processUpdatedLines(doc) }, 250);
	});
	cmEditor.on("change", function(cm, change) {
		gel('${ref}').value = cm.getValue();
		var textAreaElement = cm.getTextArea();
		textAreaElement.isFocused=false;
		multiModified(textAreaElement);
		onInputMapChange('${ref}');
	});
	cmEditor.on("keydown", function(cm, change) {
		var textAreaElement = cm.getTextArea();
		multiKeyDown(textAreaElement);
	});
	cmEditor.on("blur", function(cm, change) {
		var textAreaElement = cm.getTextArea();
		textAreaElement.isFocused=false;
	});
	cmEditor.on("focus", function(cm, change) {
		var textAreaElement = cm.getTextArea();
		textAreaElement.isFocused=true;
	});
	window.jQuery(cmEditor.display.wrapper).css("background-color", "").attr('id', "cm.${ref}");
})();
